                    mucLiveStatus.innerHTML = `⏳ <strong>NO ACTIVE POSITION (PENDING RETEST)</strong>: ${absDistPips.toFixed(0)} Pips to Entry $${entryPrice.toFixed(2)} • Intezar Karein!`;
                    mucLiveStatus.className = "muc-live-status-pill";
