// =========================================================
// ASTRONOMICAL MOON PHASE & PLANETARY TIME HARMONY ENGINE
// =========================================================
function computeLiveMoonPhase(date = new Date()) {
    // Known astronomical New Moon epoch: Jan 6, 2000, 18:14 UTC
    const knownNewMoon = new Date("2000-01-06T18:14:00Z").getTime();
    const synodicMonth = 29.53058770576 * 86400 * 1000;
    const diff = date.getTime() - knownNewMoon;
    const cycles = diff / synodicMonth;
    const phaseFraction = cycles - Math.floor(cycles);
    const ageDays = (phaseFraction * 29.530588).toFixed(1);
    const illumination = Math.round((1 - Math.cos(phaseFraction * 2 * Math.PI)) / 2 * 100);

    let phaseName = "";
    let icon = "";
    let goldImpact = "";
    let pillarState = "";
    let pillarVerdict = "";

    if (phaseFraction < 0.03 || phaseFraction > 0.97) {
        phaseName = `New Moon Phase (${illumination}% Light)`;
        icon = "🌑";
        goldImpact = `Day ${ageDays} of Cycle: Major Accumulation window. Market building higher timeframe swing lows.`;
        pillarState = "New Moon (Accumulation)";
        pillarVerdict = "Impact: 🟢 Institutional Bottom Formation";
    } else if (phaseFraction < 0.22) {
        phaseName = `Waxing Crescent Phase (${illumination}% Light)`;
        icon = "🌒";
        goldImpact = `Day ${ageDays} of Cycle: Bullish expansion building towards First Quarter liquidity targets.`;
        pillarState = "Waxing Crescent Momentum";
        pillarVerdict = "Impact: 🟢 Expansion Building Phase";
    } else if (phaseFraction < 0.28) {
        phaseName = `First Quarter Phase (${illumination}% Light)`;
        icon = "🌓";
        goldImpact = `Day ${ageDays} of Cycle: Mid-cycle volatility expansion. Sharp directional trend continuation.`;
        pillarState = "First Quarter (Half Moon)";
        pillarVerdict = "Impact: ⚡ High Volatility Mid-Cycle";
    } else if (phaseFraction < 0.47) {
        phaseName = `Waxing Gibbous Phase (${illumination}% Light)`;
        icon = "🌔";
        goldImpact = `Day ${ageDays} of Cycle: Momentum push reaching towards Full Moon liquidity pool targets.`;
        pillarState = "Waxing Gibbous Surge";
        pillarVerdict = "Impact: 🟢 Pre-Full Moon Push";
    } else if (phaseFraction < 0.53) {
        phaseName = `Full Moon Phase (${illumination}% Light)`;
        icon = "🌕";
        goldImpact = `Day ${ageDays} of Cycle: Peak liquidity sweep zone. Retail stops hunted; trend exhaustion likely.`;
        pillarState = "Full Moon Peak Liquidity";
        pillarVerdict = "Impact: 🔴 High-probability Top / Reversal";
    } else if (phaseFraction < 0.72) {
        phaseName = `Waning Gibbous Phase (${illumination}% Light)`;
        icon = "🌖";
        goldImpact = `Day ${ageDays} of Cycle: Post-peak distribution active. Bearish liquidity draw towards Asian lows.`;
        pillarState = "Waning Gibbous (Post-Peak)";
        pillarVerdict = "Impact: 🔴 Bearish Distribution Wave";
    } else if (phaseFraction < 0.78) {
        phaseName = `Last Quarter Phase (${illumination}% Light)`;
        icon = "🌗";
        goldImpact = `Day ${ageDays} of Cycle: Technical retest & order block mitigation window before cycle end.`;
        pillarState = "Last Quarter (Retest)";
        pillarVerdict = "Impact: ⚡ Mitigation / Pullback Pivot";
    } else {
        phaseName = `Waning Crescent Phase (${illumination}% Light)`;
        icon = "🌘";
        goldImpact = `Day ${ageDays} of Cycle: Final cycle exhaustion & institutional re-accumulation ahead of New Moon.`;
        pillarState = "Waning Crescent Cycle";
        pillarVerdict = "Impact: 🔴 Final Liquidation / Base Building";
    }

    return { phaseName, icon, illumination, ageDays, goldImpact, pillarState, pillarVerdict };
}

function updateAstroUI() {
    const moon = computeLiveMoonPhase();
    
    // Update Module 09 Astro Card
    const iconEl = document.getElementById("astroMoonIcon");
    const titleEl = document.getElementById("astroMoonTitle");
    const descEl = document.getElementById("astroMoonDesc");
    const equinoxDesc = document.getElementById("astroEquinoxDesc");

    if (iconEl) iconEl.textContent = moon.icon;
    if (titleEl) titleEl.textContent = moon.phaseName;
    if (descEl) descEl.textContent = moon.goldImpact;

    // Calculate days to Equinox (Sept 22)
    const now = new Date();
    const equinoxDate = new Date(now.getFullYear(), 8, 22);
    const diffDays = Math.ceil((equinoxDate - now) / (1000 * 60 * 60 * 24));
    if (equinoxDesc) {
        if (diffDays > 0) {
            equinoxDesc.textContent = `September 22-23 Quarterly Rebalancing cycle in ${diffDays} days. Historical Gold strength pivot.`;
        } else {
            equinoxDesc.textContent = `Quarterly Rebalancing cycle currently ACTIVE. Institutional portfolio re-allocation window.`;
        }
    }

    // Update Module 01 Pillar 7
    const pillarAstroState = document.getElementById("pillarAstroState");
    const pillarAstroVerdict = document.getElementById("pillarAstroVerdict");
    if (pillarAstroState) pillarAstroState.textContent = moon.pillarState;
    if (pillarAstroVerdict) pillarAstroVerdict.textContent = moon.pillarVerdict;
}
window.updateAstroUI = updateAstroUI;

// ==========================================
// FULL CACHE PURGE & HARD REAL-TIME SYNC
// ==========================================
function executeFullCachePurge() {
    try {
        // 1. Purge all Web Storage (LocalStorage & SessionStorage)
        try { localStorage.clear(); } catch(e) {}
        try { sessionStorage.clear(); } catch(e) {}

        // 2. Purge browser Cache Storage API (Service Workers / PWA caches)
        if (window.caches) {
            caches.keys().then(keys => {
                keys.forEach(key => caches.delete(key));
            }).catch(() => {});
        }

        // 3. Clear all host cookies
        try {
            document.cookie.split(";").forEach(c => {
                document.cookie = c.replace(/^ +/, "").replace(/=.*/, "=;expires=" + new Date().toUTCString() + ";path=/");
            });
        } catch(e) {}

        // 4. Visual toast confirmation
        const banner = document.createElement("div");
        banner.style.cssText = "position:fixed; top:24px; right:24px; z-index:999999; background:#00f59b; color:#0b0f19; padding:14px 22px; border-radius:8px; font-weight:900; font-family:var(--font-mono, monospace); font-size:0.88rem; box-shadow:0 0 30px rgba(0,245,155,0.8); display:flex; align-items:center; gap:8px;";
        banner.innerHTML = "🧹 <strong>CACHE 100% PURGED!</strong> Hard-Syncing Fresh Real-Time Stream...";
        document.body.appendChild(banner);

        // 5. Hard reload with fresh timestamp to bypass any browser disk/memory cache
        const ts = Date.now();
        setTimeout(() => {
            window.location.href = window.location.pathname + "?purge=" + ts + "&v=" + ts;
        }, 500);
    } catch(e) {
        window.location.reload(true);
    }
}
window.executeFullCachePurge = executeFullCachePurge;



// =========================================================
// QUANT RISK-OF-RUIN & CAPITAL SURVIVAL ENGINE
// =========================================================
function setRorRiskPreset(pct) {
    const input = document.getElementById("rorInputRiskPct");
    if (input) {
        input.value = pct;
    }
    document.querySelectorAll(".btn-ror-preset").forEach(btn => {
        btn.classList.remove("active", "safe-active");
        if (btn.textContent.includes(`${pct.toFixed(2)}%`)) {
            btn.classList.add(pct <= 0.5 ? "safe-active" : "active");
        }
    });
    recalculateRiskOfRuin();
}
window.setRorRiskPreset = setRorRiskPreset;

function recalculateRiskOfRuin() {
    try {
        const balEl = document.getElementById("rorInputBalance");
        const riskEl = document.getElementById("rorInputRiskPct");
        const wrEl = document.getElementById("rorInputWinRate");
        const pfEl = document.getElementById("rorInputPf");
        if (!balEl || !riskEl || !wrEl || !pfEl) return;

        const balance = Math.max(10, parseFloat(balEl.value) || 500);
        const riskPct = Math.max(0.05, parseFloat(riskEl.value) || 2.0);
        const winRatePct = Math.max(1, Math.min(99, parseFloat(wrEl.value) || 41.5));
        const pf = Math.max(0.1, parseFloat(pfEl.value) || 1.18);

        const r = riskPct / 100;
        const w = winRatePct / 100;
        const q = 1 - w;
        const avgWinR = w > 0 ? (pf * q) / w : 1.0;
        const edge = (w * avgWinR - q) / (w * avgWinR + q);

        const maxStreak = 16;
        const maxDdR = 42.40;

        const dollarRisk = balance * r;
        const streakLoss = maxStreak * dollarRisk;
        const streakLossPct = (streakLoss / balance) * 100;
        const ddLoss = maxDdR * dollarRisk;
        const ddLossPct = (ddLoss / balance) * 100;
        const remainingBalance = Math.max(0, balance - ddLoss);

        // Calculate Probability of severe drawdown / ruin
        const unitsToHalf = 0.50 / r;
        const rorHalfPct = edge > 0 ? Math.min(100, Math.pow((1 - edge) / (1 + edge), unitsToHalf) * 100) : 100;

        // Metric Boxes
        const valProb = document.getElementById("rorValProb");
        const descProb = document.getElementById("rorDescProb");
        const boxProb = document.getElementById("rorBoxProb");
        if (valProb && descProb && boxProb) {
            if (ddLossPct >= 70) {
                valProb.textContent = "CRITICAL (85%)";
                valProb.className = "ror-box-val text-down";
                descProb.textContent = "Severe ruin threat: -42.4R wipes out account";
                boxProb.className = "ror-metric-box danger";
            } else if (ddLossPct >= 35) {
                valProb.textContent = "HIGH STRESS";
                valProb.className = "ror-box-val text-down";
                descProb.textContent = "Heavy drawdown: account down >40%";
                boxProb.className = "ror-metric-box danger";
            } else if (ddLossPct >= 20) {
                valProb.textContent = "MODERATE";
                valProb.className = "ror-box-val text-up";
                descProb.textContent = "Standard retracement window (~21%)";
                boxProb.className = "ror-metric-box safe";
            } else {
                valProb.textContent = "< 0.1% (SAFE)";
                valProb.className = "ror-box-val text-up";
                descProb.textContent = "Institutional safe haven position";
                boxProb.className = "ror-metric-box safe";
            }
        }

        const valDrawdown = document.getElementById("rorValDrawdown");
        const descDrawdown = document.getElementById("rorDescDrawdown");
        if (valDrawdown && descDrawdown) {
            valDrawdown.textContent = `-$${ddLoss.toFixed(2)}`;
            descDrawdown.textContent = `${ddLossPct.toFixed(1)}% of $${balance.toFixed(0)} Account Lost`;
        }

        const valStreak = document.getElementById("rorValStreak");
        const descStreak = document.getElementById("rorDescStreak");
        if (valStreak && descStreak) {
            valStreak.textContent = `-$${streakLoss.toFixed(2)}`;
            descStreak.textContent = `-${streakLossPct.toFixed(1)}% Account Hit in 16 Losses`;
        }

        // Populate Survival Matrix Table
        const tbody = document.getElementById("rorMatrixBody");
        if (tbody) {
            const tiers = [
                { label: "0.25% Institutional Micro", pct: 0.25 },
                { label: "0.50% Conservative Safe", pct: 0.50 },
                { label: "1.00% Standard Professional", pct: 1.00 },
                { label: "2.00% Aggressive (Old Setting)", pct: 2.00 }
            ];

            tbody.innerHTML = tiers.map(t => {
                const tRisk = balance * (t.pct / 100);
                const tStreak = maxStreak * tRisk;
                const tDD = maxDdR * tRisk;
                const tRemain = Math.max(0, balance - tDD);
                const isSelected = Math.abs(riskPct - t.pct) < 0.05;
                const isDanger = t.pct >= 1.5;
                const isSafe = t.pct <= 0.5;
                const rowClass = isDanger ? "tier-danger" : (isSafe ? "tier-safe" : "");
                const statusBadge = isDanger ? "🛑 CRITICAL RUIN RISK" : (isSafe ? "🟢 SURVIVABLE EDGE" : "⚠️ HIGH DRAWDOWN");

                return `
                    <tr class="${rowClass}" style="${isSelected ? 'outline: 2px solid var(--color-cyan);' : ''}">
                        <td><strong>${t.label}</strong> ${isSelected ? '◄ ACTIVE' : ''}</td>
                        <td>$${tRisk.toFixed(2)}</td>
                        <td style="color:var(--color-red);">-$${tStreak.toFixed(2)} (-${(t.pct * maxStreak).toFixed(1)}%)</td>
                        <td style="color:var(--color-red);">-$${tDD.toFixed(2)} (-${(t.pct * maxDdR).toFixed(1)}%)</td>
                        <td style="font-weight:800; color:${tRemain < balance * 0.4 ? 'var(--color-red)' : 'var(--color-green)'};">$${tRemain.toFixed(2)}</td>
                        <td><span style="font-weight:800;">${statusBadge}</span></td>
                    </tr>
                `;
            }).join("");
        }

        // Live Verdict Banner
        const banner = document.getElementById("rorVerdictBanner");
        if (banner) {
            if (ddLossPct >= 70) {
                banner.style.background = "rgba(255, 59, 92, 0.15)";
                banner.style.borderColor = "#ff3b5c";
                banner.style.color = "#fca5a5";
                banner.innerHTML = `⚠️ <strong>CRITICAL RISK WARNING:</strong> At <strong>${riskPct.toFixed(1)}% risk ($${dollarRisk.toFixed(2)}/trade)</strong>, the 1-year max drawdown of <strong>-42.4R destroys ${ddLossPct.toFixed(1)}% of your account</strong> (leaving only $${remainingBalance.toFixed(2)}). The 16-trade losing streak alone wipes out $${streakLoss.toFixed(2)}. <strong>To trade this 41.5% WR edge safely without risk of ruin, maximum allocation must not exceed 0.50% ($${(balance * 0.005).toFixed(2)} per trade).</strong>`;
            } else if (ddLossPct >= 35) {
                banner.style.background = "rgba(245, 158, 11, 0.15)";
                banner.style.borderColor = "#f59e0b";
                banner.style.color = "#fde68a";
                banner.innerHTML = `⚠️ <strong>HIGH VOLATILITY DRAWDOWN:</strong> At <strong>${riskPct.toFixed(1)}% risk</strong>, expect a historical max drawdown of <strong>-${ddLossPct.toFixed(1)}% ($${ddLoss.toFixed(2)})</strong>. Account remains solvent ($${remainingBalance.toFixed(2)} balance), but psychological tolerance for a 16-loss streak ($${streakLoss.toFixed(2)}) is required.`;
            } else {
                banner.style.background = "rgba(0, 245, 155, 0.12)";
                banner.style.borderColor = "#00f59b";
                banner.style.color = "#6ee7b7";
                banner.innerHTML = `🛡️ <strong>INSTITUTIONAL SAFE HAVEN APPROVED:</strong> At <strong>${riskPct.toFixed(2)}% risk ($${dollarRisk.toFixed(2)}/trade)</strong>, the worst historical drawdown is strictly capped at <strong>-${ddLossPct.toFixed(1)}% ($${ddLoss.toFixed(2)})</strong>, preserving <strong>$${remainingBalance.toFixed(2)}</strong> of capital even across the maximum 16-loss cluster. This position sizing completely neutralizes ruin risk.`;
            }
        }
    } catch(e) {
        console.error("recalculateRiskOfRuin error:", e);
    }
}
window.recalculateRiskOfRuin = recalculateRiskOfRuin;
